<?php
require __DIR__ . '/inc/boot.php';
$u = biz_require(); biz_need('reports.view'); biz_need_module('reports'); $a = account(); $pdo = db(); $aid = (int) $a['id']; $cur = $a['currency'];
$myBranch = biz_branch(); $branches = biz_branches($aid, false); $bid = $myBranch ?: (int) ($_GET['branch'] ?? 0);
$from = valid_date((string) ($_GET['from'] ?? '')) ? $_GET['from'] : gmdate('Y-m-01'); $to = valid_date((string) ($_GET['to'] ?? '')) ? $_GET['to'] : gmdate('Y-m-d'); $cust = (int) ($_GET['customer'] ?? 0);
$w = 'd.account_id = ? AND d.status = ? AND d.doc_date >= ? AND d.doc_date <= ?'; $bind = fn(string $st) => [$aid, $st, $from, $to];
$bsql = $bid ? ' AND d.id IN (SELECT document_id FROM biz_doc_meta WHERE branch_id = ?)' : ''; $bb = $bid ? [$bid] : [];
$tot = function (string $type) use ($pdo, $w, $bind, $bsql, $bb, $cust) { $q = $pdo->prepare("SELECT COUNT(*) c, COALESCE(SUM(d.total),0) t FROM biz_documents d WHERE $w AND d.doc_type = ?" . $bsql . ($cust ? ' AND d.customer_id = ?' : '')); $q->execute([...$bind('posted'), $type, ...$bb, ...($cust ? [$cust] : [])]); $r = $q->fetch(); return [(int) $r['c'], db_cents($r['t'])]; };
$sum = []; foreach (BIZ_TYPES as $t) $sum[$t] = $tot($t);
$byBranch = []; if (!$myBranch) { foreach ($branches as $b) { $q = $pdo->prepare("SELECT d.doc_type, COALESCE(SUM(d.total),0) t FROM biz_documents d JOIN biz_doc_meta m ON m.document_id = d.id WHERE $w AND m.branch_id = ? AND d.doc_type IN ('invoice','receipt') GROUP BY d.doc_type"); $q->execute([...$bind('posted'), $b['id']]); $r = $q->fetchAll(PDO::FETCH_KEY_PAIR); $byBranch[] = [$b, db_cents($r['invoice'] ?? 0), db_cents($r['receipt'] ?? 0)]; } }
$top = $pdo->prepare("SELECT d.customer_name, COUNT(*) c, SUM(d.total) t FROM biz_documents d WHERE $w AND d.doc_type = 'invoice'" . $bsql . " GROUP BY d.customer_name ORDER BY t DESC LIMIT 8"); $top->execute([...$bind('posted'), ...$bb]); $top = $top->fetchAll();
$hist = []; $cname = ''; if ($cust) { $q = $pdo->prepare('SELECT name FROM biz_customers WHERE id = ? AND account_id = ?'); $q->execute([$cust, $aid]); $cname = (string) $q->fetchColumn();
    if ($cname !== '') { $q = $pdo->prepare('SELECT d.* FROM biz_documents d WHERE d.account_id = ? AND d.customer_id = ?' . $bsql . ' ORDER BY d.id DESC LIMIT 100'); $q->execute([$aid, $cust, ...$bb]); $hist = $q->fetchAll(); } }
if (isset($_GET['csv'])) { header('Content-Type: text/csv; charset=utf-8'); header('Content-Disposition: attachment; filename="report.csv"'); $o = fopen('php://output', 'w'); fputcsv($o, ['Type', 'Documents', 'Total (' . $cur . ')']); foreach ($sum as $t => [$c, $v]) fputcsv($o, [DOC_TYPES[$t]['plural'], $c, dec($v)]); biz_audit('report_export', "$from to $to"); exit; }
$custs = $pdo->prepare('SELECT id, name FROM biz_customers WHERE account_id = ? ORDER BY name LIMIT 500'); $custs->execute([$aid]); $custs = $custs->fetchAll();
biz_head('Reports', 'rep'); ?>
<form class="card" method="get"><div class="two"><label>From<input type="date" name="from" value="<?= h($from) ?>"></label><label>To<input type="date" name="to" value="<?= h($to) ?>"></label>
<?php if (!$myBranch && $branches): ?><label>Branch<select name="branch"><option value="">All branches (whole business)</option><?php foreach ($branches as $b): ?><option value="<?= (int) $b['id'] ?>"<?= $bid === (int) $b['id'] ? ' selected' : '' ?>><?= h($b['name']) ?></option><?php endforeach; ?></select></label><?php endif; ?>
<label>Customer<select name="customer"><option value="">All customers</option><?php foreach ($custs as $c): ?><option value="<?= (int) $c['id'] ?>"<?= $cust === (int) $c['id'] ? ' selected' : '' ?>><?= h($c['name']) ?></option><?php endforeach; ?></select></label></div>
<div class="actions"><button class="btn">Show</button><button class="btn ghost" name="csv" value="1">Export CSV</button></div></form>
<div class="stats"><?php foreach ($sum as $t => [$c, $v]): ?><div class="stat"><small><?= h(DOC_TYPES[$t]['plural']) ?> (<?= $c ?>)</small><b><?= h(dmoney($v, $cur)) ?></b></div><?php endforeach; ?></div>
<?php if ($byBranch): ?><div class="card"><h2>By branch</h2><div class="list"><?php foreach ($byBranch as [$b, $i, $r]): ?><div class="row"><div><b><?= h($b['name']) ?></b></div><div class="r"><small>Invoiced <?= h(dmoney($i, $cur)) ?></small><small>Received <?= h(dmoney($r, $cur)) ?></small></div></div><?php endforeach; ?></div></div><?php endif; ?>
<div class="card"><h2>Top customers (invoiced)</h2><div class="list"><?php foreach ($top as $t): ?><div class="row"><div><b><?= h($t['customer_name']) ?></b><small><?= (int) $t['c'] ?> invoice(s)</small></div><div class="r"><b><?= h(dmoney(db_cents($t['t']), $cur)) ?></b></div></div><?php endforeach; if (!$top): ?><p class="muted">No invoices in this period.</p><?php endif; ?></div></div>
<?php if ($cname !== ''): ?><div class="card"><h2>History: <?= h($cname) ?></h2><div class="list"><?php foreach ($hist as $d): ?><a class="row" href="doc.php?id=<?= (int) $d['id'] ?>"><div><b><?= h($d['doc_no']) ?></b><small><?= h(fmt_date($d['doc_date'])) ?></small></div><div class="r"><b><?= h(dmoney(db_cents($d['total']), $d['currency'])) ?></b><span class="pill <?= h($d['status']) ?>"><?= h(ucfirst($d['status'])) ?></span></div></a><?php endforeach; if (!$hist) : ?><p class="muted">No documents.</p><?php endif; ?></div></div><?php endif; ?>
<?php biz_foot();
